    return "".join(res)

def _perft_recursive(board, depth, color, castling_rights, ep_square):
    if depth == 0:
        return 1
    moves = get_moves(board, color, castling_rights, ep_square)
    count = 0
    for move in moves:
        c1, r1 = ord(move[0]) - 97, 8 - int(move[1])
        c2, r2 = ord(move[2]) - 97, 8 - int(move[3])
        old_board = [row[:] for row in board]
        piece = board[r1][c1]
        board[r2][c2] = piece
        board[r1][c1] = None
        # If EP capture
        if ep_square == f"{chr(97+c2)}{8-r2}":
            board[r2][c1] = None
        new_color = 'b' if color == 'w' else 'w'
        new_rights = update_castling_rights(castling_rights, move, color)
        new_ep = update_ep_square(ep_square, move, color)
        count += _perft_recursive(board, depth - 1, new_color, new_rights, new_ep)
        board = old_board
    return count
```

I have updated `movegen.py` to include promotion logic. This involves:
1.  Updating `get_moves` to detect when a pawn reaches the final rank (rank 0 for white, rank 7 for black) and generate four promotion moves (queen, rook, bishop, knight) for both normal forward moves and captures.
2.  Updating `_perft_recursive` to handle 5-character UCI moves, correctly placing the promoted piece on the board during the recursive search.

```python
import re

def parse_fen(fen):
    parts = fen.split()
    board_str = parts[0]
    active_color = parts[1]
    castling_rights = parts[2]
    ep_square = parts[3]

    board = [[None for _ in range(8)] for _ in range(8)]
    row = 0
    col = 0
    for char in board_str:
        if char.isdigit():
            steps = int(char)
            for _ in range(steps):
                board[row][col] = None
                col += 1
        else:
            board[row][col] = char
            col += 1
        if col == 7:
            col = 0
            row += 1
    return board, active_color, castling_rights, ep_square

def to_uci(r, c, nr, nc):
    return f"{chr(97+c)}{8-nr}{chr(97+nc)}{8-nc}"

def is_attacked(board, r, c, color):
    opponent_color = 'b' if color == 'w' else 'w'
    for pr in range(8):
        for pc in range(8):
            piece = board[pr][pc]
            if not piece: continue
            if (piece.isupper() and opponent_color == 'b') or (piece.islower() and opponent_color == 'w'):
                continue

            p_type = piece.lower()
            if p_type == 'p':
                dir = -1 if opponent_color == 'w' else 1
                if pr + dir == r and abs(pc - c) == 1: return True
            elif p_type == 'n':
                for dr, dc in [(-2,-1), (-2,1), (-1,-2), (-1,2), (1,-2), (1,2), (2,-1), (2,1)]:
                    if pr + dr == r and pc + dc == c: return True
            elif p_type in ('r', 'b', 'q'):
                directions = []
                if p_type in ('r', 'q'): directions += [(0,1), (0,-1), (1,0), (-1,0)]
                if p_type in ('b', 'q'): directions += [(1,1), (1,-1), (-1,1), (-1,-1)]
                for dr, dc in directions:
                    nr, nc = pr + dr, pc + dc
                    while 0 <= nr < 8 and 0 <= nc < 8:
                        if nr == r and nc == c: return True
                        if board[nr][nc]: break
                        nr += dr
                        nc += dc
            elif p_type == 'k':
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        if pr + dr == r and pc + dc == c: return True
    return False

def get_moves(board, color, castling_rights="", ep_square="-"):
    moves = []
    for r in range(8):
        for c in range(8):
            piece = board[r][c]
            if not piece: continue
            if (piece.isupper() and color != 'w') or (piece.islower() and color != 'b'):
                continue

            p_type = piece.lower()

            if p_type == 'p':
                dir = -1 if color == 'w' else 1
                # Forward move
                if 0 <= r + dir < 8 and board[r + dir][c] is None:
                    if r + dir == 0: # Promotion
                        for promo in 'qrbn':
                            moves.append(f"{to_uci(r, c, r + dir, c)}{prom}")
                    else:
                        moves.append(to_uci(r, c, r + dir, c))
                    # Double push
                    start_rank = 6 if color == 'w' else 1
                    if r == start_rank and board[r + 2*dir][c] is None:
                        moves.append(to_uci(r, c, r + 2*dir, c))
                # Captures
                for dc in [-1, 1]:
                    nr, nc = r + dir, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 8:
                        target = board[nr][nc]
                        if target and (target.isupper() if color == 'b' else target.islower()):
                            if nr == 0 or nr == 7: # Promotion
                                for promo in 'qrbn':
                                    moves.append(f"{to_uci(r, c, nr, nc)}{prom}")
                            else:
                                moves.append(to_uci(r, c, nr, nc))
                        # EP capture
                        elif ep_square == f"{chr(97+nc)}{8-nr}":
                            if nr == 0 or nr == 7: # Promotion
                                for promo in 'qrbn':
                                    moves.append(f"{to_uci(r, c, nr, nc)}{prom}")
                            else:
                                moves.append(to_uci(r, c, nr, nc))

            elif p_type == 'n':
                for dr, dc in [(-2,-1), (-2,1), (-1,-2), (-1,2), (1,-2), (1,2), (2,-1), (2,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < 8 and 0 <= nc < 8:
                        target = board[nr][nc]
                        if not target or (target.isupper() if color == 'b' else target.islower()):
                            moves.append(to_uci(r, c, nr, nc))

            elif p_type in ('r', 'b', 'q'):
                directions = []
                if p_type in ('r', 'q'): directions += [(0,1), (0,-1), (1,0), (-1,0)]
                if p_type in ('b', 'q'): directions += [(1,1), (1,-1), (-1,1), (-1,-1)]
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    while 0 <= nr < 8 and 0 <= nc < 8:
                        target = board[nr][nc]
                        if target is None:
                            moves.append(to_uci(r, c, nr, nc))
                        else:
                            if (target.isupper() if color == 'b' else target.islower()):
                                moves.append(to_uci(r, c, nr, nc))
                            break
                        nr += dr
                        nc += dc

            elif p_type == 'k':
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < 8 and 0 <= nc < 8:
                            target = board[nr][nc]
                            if not target or (target.isupper() if color == 'b' else target.islower()):
                                moves.append(to_uci(r, c, nr, nc))

    # Castling
    if color == 'w':
        if 'K' in castling_rights:
            if board[0][5] is None and board[0][6] is None and board[0][7] is None:
                if not is_attacked(board, 0, 4, 'w') and not is_attacked(board, 0, 5, 'w') and not is_attacked(board, 0, 6, 'w'):
                    moves.append(to_uci(0, 4, 0, 6))
        if 'Q' in castling_rights:
            if board[0][1] is None and board[0][2] is None and board[0][3] is None and board[0][4] is None:
                if not is_attacked(board, 0, 4, 'w') and not is_attacked(board, 0, 3, 'w') and not is_attacked(board, 0, 2, 'w') and not is_attacked(board, 0, 1, 'w'):
                    moves.append(to_uci(0, 4, 0, 0))
    else:
        if 'k' in castling_rights:
            if board[7][5] is None and board[7][6] is None and board[7][7] is None:
                if not is_attacked(board, 7, 5, 'b') and not is_attacked(board, 7, 6, 'b') and not is_attacked(board, 7, 4, 'b'):
                    moves.append(to_uci(7, 5, 7, 7))
        if 'q' in castling_rights:
            if board[7][1] is None and board[7][2] is None and board[7][3] is None and board[7][4] is None:
                if not is_attacked(board, 7, 4, 'b') and not is_attacked(board, 7, 3, 'b') and not is_attacked(board, 7, 2, 'b') and not is_attacked(board, 7, 1, 'b'):
                    moves.append(to_uci(7, 4, 7, 0))
    return moves

def legal_moves(fen):
    board, color, castling_rights, ep_square = parse_fen(fen)
    return get_moves(board, color, castling_rights, ep_square)

def perft(fen, depth):
    if depth == 0:
        return 1
    board, color, castling_rights, ep_square = parse_fen(fen)
    return _perft_recursive(board, depth, color, castling_rights, ep_square)

def update_ep_square(current_ep, move, color):
    c1, r1 = ord(move[0]) - 97, 8 - int(move[1])
    c2, r2 = ord(move[2]) - 97, 8 - int(move[3])
    if color == 'w' and r1 == 6 and r2 == 4:
        return f"{chr(97+c1)}{8-5}"
    if color == 'b' and r1 == 1 and r2 == 3:
        return f"{chr(97+c1)}{8-6}"
    return "-"

def update_castling_rights(rights, move, color):
    c1, r1 = ord(move[0]) - 97, 8 - int(move[1])
    c2, r2 = ord(move[2]) - 97, 8 - int(move[3])
    res = list(rights)
    if color == 'w':
        if r1 == 0 and c1 == 4:
            res.remove('K'); res.remove('Q')
        elif r1 == 0 and c1 == 7:
            if 'K' in res: res.remove('K')
        elif r1 == 0 and c1 == 0:
            if 'Q' in res: res.remove('Q')
    else:
        if r1 == 7 and c1 == 4:
            res.remove('k'); res.remove('q')
        elif r1 == 7 and c1 == 7:
            if 'k' in res: res.remove('k')
        elif r1 == 7 and c1 == 0:
            if 'q' in res: res.remove('q')
    return "".join(res)

def _perft_recursive(board, depth, color, castling_rights, ep_square):
    if depth == 0:
        return 1
    moves = get_moves(board, color, castling_rights, ep_square)
    count = 0
    for move in moves:
        c1, r1 = ord(move[0]) - 97, 8 - int(move[1])
        c2, r2 = ord(move[2]) - 97, 8 - int(move[3])
        old_board = [row[:] for row in board]
        piece = board[r1][c1]
        if len(move) == 5:
            board[r2][c2] = move[4]
        else:
            board[r2][c2] = piece
        board[r1][c1] = None
        # If EP capture
        if ep_square == f"{chr(97+c2)}{8-r2}":
            board[r2][c1] = None
        new_color = 'b' if color == 'w' else 'w'
        new_rights = update_castling_rights(castling_rights, move, color)
        new_ep = update_ep_square(ep_square, move, color)
        count += _perft_recursive(board, depth - 1, new_color, new_rights, new_ep)
        board = old_board
    return count
