2.  Updating `legal_moves` to simulate each pseudo-legal move.
3.  The simulation correctly handles promotions, en passant captures, and the rook movement during castling.
4.  Each move is validated using `is_attacked` to ensure the king is not in check after the move.

```python
def find_king(board, color):
    target_piece = 'K' if color == 'w' else 'k'
    for r in range(8):
        for c in range(8):
            if board[r][c] == target_piece:
                return r, c
    return None

def legal_moves(fen):
    board, color, castling_rights, ep_square = parse_fen(fen)
    pseudo_moves = get_moves(board, color, castling_rights, ep_square)
    legal = []

    for move in pseudo_moves:
        c1, r1 = ord(move[0]) - 97, 8 - int(move[1])
        c2, r2 = ord(move[2]) - 97, 8 - int(move[3])

        old_board = [row[:] for row in board]
        piece = board[r1][c1]

        # Move piece
        if len(move) == 5:
            board[r2][c2] = move[4]
        else:
            board[r2][c2] = piece
        board[r1][c1] = None

        # Handle EP capture
        if ep_square == f"{chr(97+c2)}{8-r2}":
            board[r2][c1] = None

        # Handle Castling Rook
        if len(move) == 4:
            if color == 'w':
                if c2 == 6:
                    board[0][7] = board[0][5]
                    board[0][5] = None
                elif c2 == 0:
                    board[0][0] = board[0][1]
                    board[0][1] = None
            else:
                if c2 == 7:
                    board[7][7] = board[7][5]
                    board[7][5] = None
                elif c2 == 0:
                    board[7][0] = board[7][1]
                    board[7][1] = None

        kr, kc = find_king(board, color)
        if kr is not None and not is_attacked(board, kr, kc, color):
            legal.append(move)

        board = old_board
    return legal
